import{_ as r,E as n,h as o,c as i,b as a,f as s,H as d,a4 as c}from"./chunks/framework.B_fYP6Of.js";const g=JSON.parse('{"title":"ADR 001 · Serving boundaries","description":"An architecture decision record on the proposed SvelteKit and Rust boundary, with alternatives and concrete measurements for streaming, cancellation, and recovery.","frontmatter":{"title":"ADR 001 · Serving boundaries","description":"An architecture decision record on the proposed SvelteKit and Rust boundary, with alternatives and concrete measurements for streaming, cancellation, and recovery.","teaser":"A reader gets the first line of an answer and then loses the connection. The design of that handoff matters more than the framework names."},"headers":[],"relativePath":"decisions/001-serving-boundaries.md","filePath":"decisions/001-serving-boundaries.md"}'),l={name:"decisions/001-serving-boundaries.md"};function h(p,e,u,m,v,f){const t=n("LabArticleHeader");return o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"adr-001-·-serving-boundaries",tabindex:"-1"},[s("ADR 001 · Serving boundaries "),a("a",{class:"header-anchor",href:"#adr-001-·-serving-boundaries","aria-label":'Permalink to "ADR 001 · Serving boundaries"'},"​")],-1)),d(t),e[1]||(e[1]=c('<p><em>Architecture decision record · Proposed baseline.</em></p><p>This record asks where live chat should run after the first page loads. It sets out a starting architecture and the measurements that could change the choice.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A useful comparison starts with the reader’s experience. How long until a cited answer appears? Can the reader keep typing while it arrives, stop it, and recover after a disconnect? Measure browser responsiveness, retrieval, inference, cancellation, and recovery together. Developer familiarity alone cannot settle the choice.</p><h2 id="proposed-decision" tabindex="-1">Proposed decision <a class="header-anchor" href="#proposed-decision" aria-label="Permalink to &quot;Proposed decision&quot;">​</a></h2><p>Use Svelte 5, SvelteKit, and TypeScript for the product interface. Use Rust with Axum/Tokio for the live chat service. Let SvelteKit render initial routes and bounded snapshots where useful, then deliver active answer events directly from Rust over SSE. HTTP commands create and cancel runs.</p><p>Keep run policies and evidence handling in application/domain modules with focused ports. Axum, model protocols, NATS, and SQLite are adapters. This is a dependency rule, not a mandate for multiple services or one abstraction per function.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>React with Vite or Next.js remains viable. Go or a carefully isolated FastAPI backend may perform similarly when external model work dominates. Svelte&#39;s reactive model and Rust&#39;s resource control motivate the starting choice; no comparative application benchmark has established a winner.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The split gives the UI responsibility for its event client, state reducer, snapshot cursor, replay gaps, and cancellation protocol. Initial page rendering and live answer delivery follow separate paths. Add retained output fanout when independent generation or multiple viewers create a need for it.</p><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Compare first visible grounded text, input responsiveness, chunk gaps, memory, long tasks, and cancellation under realistic histories. Test slow devices and concurrent streams. Confirm one terminal state and safe replay under reconnects. See <a href="/knowledge-lab/architecture/frontend">frontend</a>, <a href="/knowledge-lab/architecture/backend">backend</a>, and <a href="/knowledge-lab/architecture/contracts">contracts</a>.</p>',13))])}const w=r(l,[["render",h]]);export{g as __pageData,w as default};
